function onSubmit(e) {
  var r = e.response.getItemResponses(), body = {};
  r.forEach(function (i) { body[i.getItem().getTitle().toLowerCase()] = i.getResponse(); });
  UrlFetchApp.fetch('{ADDRESS}', {method: 'post', contentType: 'application/json', payload: JSON.stringify(body), muteHttpExceptions: true});
}

function onRow(e) {
  var s = SpreadsheetApp.getActiveSheet(), last = s.getLastRow();
  var h = s.getRange(1, 1, 1, s.getLastColumn()).getValues()[0], v = s.getRange(last, 1, 1, h.length).getValues()[0], body = {};
  h.forEach(function (k, i) { body[String(k).toLowerCase()] = v[i]; });
  UrlFetchApp.fetch('{ADDRESS}', {method: 'post', contentType: 'application/json', payload: JSON.stringify(body), muteHttpExceptions: true});
}
